// Generated by npm run service-worker. Cache only the public application shell.
const CACHE='readbook-shell-ddf776f12eb19c0e';
const SHELL=["/app.js","/appearance.js","/editor-actions.js","/icon.svg","/icons.js","/icons/app-192.png","/icons/app-512.png","/icons/apple-touch-icon.png","/icons/maskable-512.png","/","/listen-session.js","/listening-wake-lock.js","/manifest.webmanifest","/markdown.js","/narration-player.js","/offline-store.js","/pwa.js","/reading-pages.js","/sound-mixer.js","/speech-chunks.js","/speech-text.js","/style.css","/vendor/marked.js","/vendor/purify.js"];
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache=await caches.open(CACHE);
  await cache.addAll(SHELL.map(url=>new Request(url,{cache:'reload'})));
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  for(const key of await caches.keys())if(key.startsWith('readbook-shell-')&&key!==CACHE)await caches.delete(key);
  await self.clients.claim();
})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')void self.skipWaiting();});
self.addEventListener('fetch',event=>{
  const url=new URL(event.request.url);
  if(event.request.method!=='GET'||url.origin!==self.location.origin||!SHELL.includes(url.pathname))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    return await cache.match(url.pathname)||fetch(event.request);
  })());
});
